import Base
import ../types.bend as T
import ../../../runtime/src/f64.bend as F
import ../../../runtime/src/record.bend as R

def number(value: F.Decoded) -> Bool:
  match value:
    case F.Finite{_, _, _}: True{}
    case _: False{}

# Validate the numeric leaves before serializing a provider payload.
def valid(value: T.JsonValue) -> Bool:
  match value:
    case T.JsonNumber{value}: number(F.decode(value))
    case T.JsonArray{Nil{}}: True{}
    case T.JsonArray{head <> rest}: valid(head) && valid(T.JsonArray{rest})
    case T.JsonObject{R.Record{Nil{}}}: True{}
    case T.JsonObject{R.Record{R.Property{_, value} <> rest}}: valid(value) && valid(T.JsonObject{R.Record{rest}})
    case _: True{}
